# Parse the edges and find parents of aab3238922
edges_text = context.split("The graph has the following edges:\n")[1].split("\n\nOperation:")[0]

parents = set()
for line in edges_text.strip().split('\n'):
    if '->' in line:
        source, target = line.split(' -> ')
        if target == 'aab3238922':
            parents.add(source)

print("Parents of aab3238922:", sorted(parents))
print("Count:", len(parents))
